arguments.new_str:
using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL
            // queries (SELECT … WHERE c.Discriminator = 'Product') depend on it.
            // Restore the EF 8 property name so old docs remain readable.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed.
            // EF Core 9 stores the raw key ("123") instead of "Product|123".
            // Existing documents use the old composite format.
            // Map a shadow property that preserves the legacy format.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGeneratorFactory<LegacyIdValueGeneratorFactory>();

            // BREAKING CHANGE 3 — HasIndex is ignored for Cosmos in EF 9
            // and now throws at runtime. Cosmos indexes are managed through
            // the Azure portal or indexing policy, not EF model config.
            // Removed: entity.HasIndex(p => p.Sku);
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } = "";  }

// Value generator that reproduces the EF 8 "EntityType|Key" id format
// so new documents are compatible with the 500K existing ones.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var pk = entry.Property("Id").CurrentValue;
        return $"{entityType}|{pk}";
    }
}

class LegacyIdValueGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new LegacyIdValueGenerator();
}

